/**
 * api/lib/fonts.js — GÉNÉRÉ (comme logo.js), ne pas éditer à la main.
 * Polices de marque embarquées en base64 (vrais TTF, transcodés depuis les
 * WOFF @fontsource — sous-ensemble « latin » : accents FR + ponctuation fine).
 * Toujours disponibles dans la lambda serverless Vercel, zéro fetch réseau.
 *   - Playfair Display 700        → nom de la maison, titres, référence
 *   - Playfair Display 500 italic → citations chaleureuses
 *   - Caveat 700                  → signature manuscrite « Maman Colombe »
 * Source : Google Fonts / @fontsource (licence OFL).
 */
function b64ToBuf(b64) { return Buffer.from(b64, "base64"); }

const playfairBold = b64ToBuf(
""
);

const playfairItalic = b64ToBuf(
""
);

const caveatBold = b64ToBuf(
""
);

export const FONTS = { playfairBold, playfairItalic, caveatBold };
